from pathlib import Path
import json,shutil,sys
b=Path(__file__).resolve().parent.parent;source=Path(sys.argv[1]);dest=b/'Captures';dest.mkdir(exist_ok=True)
provenance={}
for folder in sys.argv[1:]:
 for f in Path(folder).glob('Mechanics_*.png'):
  shutil.copy2(f,dest/f.name);provenance[f.name]=str(f)
(b/'QA/CaptureProvenance.json').write_text(json.dumps(provenance,indent=2))
groups=[('Mixed board',['StyleR10_Mixed']),('Crate stages',['StyleR10_Crate_Intact','StyleR10_Crate_Damaged','StyleR10_Crate_Cleared']),('Ice stages',['StyleR10_Ice_Intact','StyleR10_Ice_Damaged','StyleR10_Ice_Cleared']),('Chain stages',['StyleR10_Chain_Intact','StyleR10_Chain_Damaged','StyleR10_Chain_Cleared']),('Seal stages',['Seal_Intact','Seal_Cracked','Seal_Cleared']),('Directional piece',['LineR9_Before']),('Rainbow prism',['StyleR10_Color']),('Firebird special',['SparkR9_Before']),('Bomb activation',['BombR9_Before']+['BombR9_'+str(i).zfill(2) for i in range(10)])]
manifest=[{'title':title,'files':['Mechanics_'+name+'.png' for name in names]} for title,names in groups]
assert all((dest/f).exists() for g in manifest for f in g['files'])
(b/'QA/CaptureManifest.json').write_text(json.dumps(manifest,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gameplay Mechanics R10 — Board art</title><style>body{background:#0d1520;color:#ecdfc5;font:17px/1.5 system-ui;margin:0}main{max-width:900px;padding:22px;margin:auto}h1{font-size:28px;color:#e3bd73}a{color:#9bd1f2}button,select{font:inherit;padding:8px;background:#203044;color:#fff1d3;border:1px solid #8d764e;border-radius:5px;max-width:100%}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.viewport{overflow:auto}#frame{display:block;width:min(100%,576px);height:auto;margin:auto}#frame.native{width:576px;max-width:none}#caption{overflow-wrap:anywhere}.note{color:#afc1d0;font-size:14px}li{margin:8px 0}</style><main><h1>Gameplay Mechanics R10 · Unified board artwork</h1><p>Simpler gem-like facets and highlights, larger directional crystal, and separate intact/damaged obstacle artwork. On-board layer numbers are removed; header goal counts remain live.</p><p><a href="AssetReview.html">Inspect sprites beside approved gems</a> · <a href="ImplementationReport.md">Implementation and verification</a> · <a href="../R9/QA/ArtCoherenceReview.md">Original findings</a></p><div class="controls"><select id="group" aria-label="Capture group"></select><button id="previous">Previous state</button><button id="next">Next state</button><button id="native">Native pixels</button></div><div class="viewport"><img id="frame" alt="Actual Unity gameplay sandbox capture"></div><p id="caption"></p><p class="note">Actual Unity PlayMode captures, one portrait at a time. Intact → damaged → cleared comes from real resolved hits. The mixed round starts with some single-layer obstacles already in their final removable state. Still captures do not establish frame rate or human visual acceptance.</p><ul><li>Crate: reinforced bands → exposed split planks.</li><li>Ice: full frost shell → broken open center.</li><li>Chain: closed loop → snapped link and cracked lock.</li><li>Seal: intact rim/rune → broken corner and split rune.</li></ul><p>Implemented in the existing development mechanics sandbox. Approved gameplay gems, shared inventory UI icons, round difficulty and R9 animation timings are preserved.</p><p>Try it from Home in Play Mode: <strong>Legends of Rus → Development → Gameplay Mechanics Sandbox</strong>. Use Fixtures for stocked boosters and Rounds for the five playtests.</p><p><a href="QA/Verification.json">Test results</a> · <a href="QA/Scope.json">Changed files</a> · <a href="Sources/FinalGeneration.json">Generation prompts</a> · <a href="Sources/CompactLineRevision.json">Directional proportion revision</a></p></main><script>const groups=MANIFEST,g=document.querySelector('#group'),img=document.querySelector('#frame');let pos=0;groups.forEach((x,i)=>{const o=document.createElement('option');o.value=i;o.textContent=x.title;g.append(o)});function show(){let x=groups[+g.value];img.src='Captures/'+x.files[pos];document.querySelector('#caption').textContent=(pos+1)+'/'+x.files.length+' · '+x.files[pos];document.querySelector('#previous').disabled=pos===0;document.querySelector('#next').disabled=pos===x.files.length-1}g.onchange=()=>{pos=0;show()};document.querySelector('#next').onclick=()=>{pos++;show()};document.querySelector('#previous').onclick=()=>{pos--;show()};document.querySelector('#native').onclick=()=>img.classList.toggle('native');show();</script></html>'''
(b/'Gameplay_Mechanics_R10_Review.html').write_text(html.replace('MANIFEST',json.dumps(manifest)))
assets=['bomb','line','spark','color','crate','ice','chain','seal'];options=''.join('<option>'+x+'</option>' for x in assets)
(b/'AssetReview.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R10 board sprite review</title><style>body{margin:20px;background:#111925;color:#edddbf;font:17px/1.5 system-ui}a{color:#9dd1f0}.controls{display:flex;gap:8px;flex-wrap:wrap}select,button{font:inherit;padding:8px}#stage{display:flex;align-items:center;gap:10px;background:#261c12;padding:16px;width:max-content;max-width:100%;box-sizing:border-box;margin:20px 0}img{width:64px;height:64px;object-fit:contain}#large{width:min(85vw,384px);height:min(85vw,384px);display:block;margin-top:20px;background:#261c12}code{overflow-wrap:anywhere}</style><h1>R10 board-piece art</h1><p>Asset inspection only; <a href="Gameplay_Mechanics_R10_Review.html">see the actual Unity implementation</a>.</p><div class="controls"><select id="asset">'''+options+'''</select><button id="damage">Show damaged</button><select id="backdrop"><option value="#261c12">Board brown</option><option value="#000000">Black</option><option value="#ffffff">White</option><option value="#ff00bb">Magenta</option></select></div><p>At 64 CSS pixels: approved sapphire · selected R10 piece · approved gold gem</p><div id="stage"><img src="../../../../Assets/LegendsOfRus/Resources/ProductionUI/GameplayReferenceAligned/gem_sapphire.png" alt="Approved sapphire"><img id="piece" alt="New board piece"><img src="../../../../Assets/LegendsOfRus/Resources/ProductionUI/GameplayReferenceAligned/gem_gold.png" alt="Approved gold"></div><img id="large" alt="Enlarged new sprite"><p id="caption"></p><p>Ice transparency is also adjusted in Unity so the underlying gem remains legible. The damaged ice and both chain sprites have real transparent openings.</p><p><a href="QA/AlphaAudit.json">Alpha measurements</a> · <a href="Sources/FinalGeneration.json">Built-in imagegen prompts</a></p><script>let damaged=false;const a=document.querySelector('#asset'),button=document.querySelector('#damage');function show(){const stages=['crate','ice','chain','seal'].includes(a.value);button.disabled=!stages;button.textContent=damaged?'Show intact':'Show damaged';const name=a.value+(stages&&damaged?'_damaged':'');const src='../../../../Assets/LegendsOfRus/Resources/ProductionUI/MechanicsBoardArtR10/'+name+'.png';document.querySelector('#piece').src=src;document.querySelector('#large').src=src;document.querySelector('#caption').textContent=name+'.png — original generated board sprite'}a.onchange=()=>{damaged=false;show()};button.onclick=()=>{damaged=!damaged;show()};document.querySelector('#backdrop').onchange=e=>{document.querySelector('#stage').style.background=e.target.value;document.querySelector('#large').style.background=e.target.value};show();</script></html>''')
print('Selected states',sum(len(x['files']) for x in manifest))
